const kinds = values("motion").size - (values("motion").has("null") ? 1 : 0);
const durations = values("durationSec").size - (values("durationSec").has("null") ? 1 : 0);
const block = kinds === 0 ? 1 : kinds * durations + (mixStatic ? 1 : 0);
